SELECT FORMAT_DATE('%Y-%m', CURRENT_DATE()) AS period, ROUND(SAFE_DIVIDE(COUNT(DISTINCT CompanyAccount), (EXTRACT(DAY FROM CURRENT_DATE()) - 1)) * EXTRACT(DAY FROM DATE_SUB(DATE_ADD(DATE_TRUNC(CURRENT_DATE(), MONTH), INTERVAL 1 MONTH), INTERVAL 1 DAY)), 0) AS value FROM `project-for-method-dw.revenue.int_syncs` WHERE SyncDate >= DATE_TRUNC(CURRENT_DATE(), MONTH) AND SyncDate < CURRENT_DATE()